const TEACHERS = {"A":"Ikbal Afan Zka","G":"Eko Mei Sugiharto, S.Pd","B":"Ambar Susetiyowati, S.Pd","H":"Bambang Muharwo, S.Pt.,M.M","C":"Galih Ade Triana, S,Pd","I":"Nur Laeli Qitfiyah, S.Pd","D":"Anggi Nur Utami, S.Pd","J":"Yulius Sutanto, S.Pd","E":"Amin Nuryanto, A.Md,Kom.","K":"Mumtazul Mahasin Al-Haqi","F":"Destio Tabah Sujarwo, S.Pd","L":"Kartiko Sugiarto, A.Md","M":"Irma Novita Sari"};

const PAGE_SIZE = 20;
let currentPage = 1;

const els = {
  search: document.getElementById("searchInput"),
  clearSearch: document.getElementById("clearSearch"),
  day: document.getElementById("dayFilter"),
  class: document.getElementById("classFilter"),
  teacher: document.getElementById("teacherFilter"),
  time: document.getElementById("timeFilter"),
  reset: document.getElementById("resetFilters"),
  body: document.getElementById("scheduleBody"),
  count: document.getElementById("resultCount"),
  empty: document.getElementById("emptyState"),
  pagination: document.getElementById("pagination"),
  activeFilters: document.getElementById("activeFilters"),
  directory: document.getElementById("teacherDirectory"),
  menuButton: document.getElementById("menuButton"),
  nav: document.getElementById("mainNav")
};

const dayOrder = ["Senin", "Selasa", "Rabu", "Kamis", "Jumat", "Sabtu"];

function uniqueSorted(values, preferredOrder = []) {
  const unique = [...new Set(values.filter(Boolean))];
  if (!preferredOrder.length) return unique.sort((a,b) => a.localeCompare(b, "id"));
  return unique.sort((a,b) => {
    const ai = preferredOrder.indexOf(a);
    const bi = preferredOrder.indexOf(b);
    if (ai !== -1 || bi !== -1) return (ai === -1 ? 999 : ai) - (bi === -1 ? 999 : bi);
    return a.localeCompare(b, "id");
  });
}

function fillSelect(select, values, preferredOrder = []) {
  const first = select.firstElementChild;
  select.innerHTML = "";
  select.appendChild(first);
  uniqueSorted(values, preferredOrder).forEach(value => {
    const option = document.createElement("option");
    option.value = value;
    option.textContent = value;
    select.appendChild(option);
  });
}

function setupFilters() {
  fillSelect(els.day, SCHEDULE.map(x => x.day), dayOrder);
  fillSelect(els.class, SCHEDULE.map(x => x.class));
  fillSelect(els.teacher, SCHEDULE.map(x => x.teacher));
  fillSelect(els.time, SCHEDULE.map(x => x.time));
}

function normalize(text) {
  return String(text ?? "").toLocaleLowerCase("id-ID").trim();
}

function getFiltered() {
  const query = normalize(els.search.value);
  return SCHEDULE.filter(item => {
    const haystack = normalize([
      item.day, item.time, item.period, item.class,
      item.subject, item.teacher, item.teacherCode
    ].join(" "));
    return (!query || haystack.includes(query))
      && (!els.day.value || item.day === els.day.value)
      && (!els.class.value || item.class === els.class.value)
      && (!els.teacher.value || item.teacher === els.teacher.value)
      && (!els.time.value || item.time === els.time.value);
  });
}

function escapeHTML(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function renderRows(items) {
  const start = (currentPage - 1) * PAGE_SIZE;
  const pageItems = items.slice(start, start + PAGE_SIZE);

  els.body.innerHTML = pageItems.map(item => `
    <tr>
      <td class="day">${escapeHTML(item.day)}</td>
      <td class="time">${escapeHTML(item.time)}</td>
      <td class="period">${escapeHTML(item.period)}</td>
      <td><span class="class">${escapeHTML(item.class)}</span></td>
      <td class="subject">${escapeHTML(item.subject)}</td>
      <td class="teacher">${item.teacher ? `${escapeHTML(item.teacher)} <span class="teacher-code">(${escapeHTML(item.teacherCode)})</span>` : "—"}</td>
    </tr>
  `).join("");

  els.empty.hidden = items.length !== 0;
}

function renderPagination(total) {
  const pages = Math.ceil(total / PAGE_SIZE);
  els.pagination.innerHTML = "";
  if (pages <= 1) return;

  const addButton = (label, page, active = false) => {
    const btn = document.createElement("button");
    btn.className = `page-button${active ? " active" : ""}`;
    btn.textContent = label;
    btn.type = "button";
    btn.addEventListener("click", () => {
      currentPage = page;
      render();
      document.getElementById("jadwal").scrollIntoView({ behavior: "smooth", block: "start" });
    });
    els.pagination.appendChild(btn);
  };

  if (currentPage > 1) addButton("←", currentPage - 1);
  for (let p = 1; p <= pages; p++) {
    if (pages > 7 && p > 2 && p < pages - 1 && Math.abs(p - currentPage) > 1) {
      if (p === 3 || p === pages - 2) {
        const dots = document.createElement("span");
        dots.textContent = "…";
        dots.style.padding = "8px";
        els.pagination.appendChild(dots);
      }
      continue;
    }
    addButton(String(p), p, p === currentPage);
  }
  if (currentPage < pages) addButton("→", currentPage + 1);
}

function renderActiveFilters() {
  const filters = [];
  if (els.search.value) filters.push(`Pencarian: ${els.search.value}`);
  if (els.day.value) filters.push(`Hari: ${els.day.value}`);
  if (els.class.value) filters.push(`Kelas: ${els.class.value}`);
  if (els.teacher.value) filters.push(`Guru: ${els.teacher.value}`);
  if (els.time.value) filters.push(`Jam: ${els.time.value}`);
  els.activeFilters.innerHTML = filters.map(f => `<span class="filter-tag">${escapeHTML(f)}</span>`).join("");
}

function renderDirectory() {
  els.directory.innerHTML = Object.entries(TEACHERS)
    .sort(([a],[b]) => a.localeCompare(b))
    .map(([code, name]) => `
      <article class="teacher-card">
        <div class="code">${escapeHTML(code)}</div>
        <div class="name">${escapeHTML(name)}</div>
      </article>
    `).join("");
}

function render() {
  const items = getFiltered();
  const pages = Math.max(1, Math.ceil(items.length / PAGE_SIZE));
  if (currentPage > pages) currentPage = pages;

  els.count.textContent = `${items.length} entri ditemukan`;
  renderRows(items);
  renderPagination(items.length);
  renderActiveFilters();
}

function resetAll() {
  els.search.value = "";
  els.day.value = "";
  els.class.value = "";
  els.teacher.value = "";
  els.time.value = "";
  currentPage = 1;
  render();
}

[els.search, els.day, els.class, els.teacher, els.time].forEach(element => {
  element.addEventListener("input", () => { currentPage = 1; render(); });
  element.addEventListener("change", () => { currentPage = 1; render(); });
});

els.clearSearch.addEventListener("click", () => {
  els.search.value = "";
  currentPage = 1;
  els.search.focus();
  render();
});

els.reset.addEventListener("click", resetAll);

els.menuButton.addEventListener("click", () => {
  const open = els.nav.classList.toggle("open");
  els.menuButton.setAttribute("aria-expanded", String(open));
});

els.nav.addEventListener("click", event => {
  if (event.target.matches("a")) {
    els.nav.classList.remove("open");
    els.menuButton.setAttribute("aria-expanded", "false");
  }
});

setupFilters();
renderDirectory();
render();
